def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n >= 100:
        return 'D'

    my = [h[0] for h in history]
    op = [h[1] for h in history]

    op_c = op.count('C')
    op_d = n - op_c
    my_c = my.count('C')

    last_my = my[-1]
    last_op = op[-1]

    recent_op = op[-10:]
    recent_c = recent_op.count('C')
    recent_d = 10 - recent_c if n >= 10 else (n - op_c)

    if n < 4:
        if last_op == 'D':
            return 'D'
        return 'C'

    # Adaptive exploit of a very cooperative opponent in mid-game.
    if n >= 12 and n < 90:
        last15 = op[-15:]
        c15 = last15.count('C')
        if c15 >= 14:
            # Strong cooperator: probe occasionally
            if n % 6 == 0:
                return 'D'
            return 'C'

    # Strong punisher / defector detection.
    if n >= 6:
        last6 = op[-6:]
        if last6.count('D') >= 5:
            return 'D' if (n % 5) != 0 else 'C'

    # Opponent just defected.
    if last_op == 'D':
        recent_d4 = op[-4:].count('D') if n >= 4 else op_d
        if recent_d4 >= 3:
            return 'D'
        if last_my == 'D':
            # Mutual defection spiral: occasionally forgive to restart cooperation
            run_dd = 0
            for i in range(n - 1, -1, -1):
                if my[i] == 'D' and op[i] == 'D':
                    run_dd += 1
                else:
                    break
            if run_dd >= 3 and rng.random() < 0.2:
                return 'C'
            return 'D'
        # I cooperated, they defected: retaliate, but forgive isolated defections sometimes
        if n >= 2 and op[-2] == 'C' and rng.random() < 0.15:
            return 'C'
        return 'D'

    # Opponent just cooperated.
    if last_my == 'D':
        # Return to cooperation; avoid endless feud.
        return 'C'

    # Both cooperated last round. Mostly stay cooperative.
    if n >= 20:
        if recent_c >= 9:
            # Very cooperative streak: occasional probing (less exploitative late).
            if n < 90 and n % 9 == 0:
                return 'D'
            return 'C'
        if recent_c >= 6:
            return 'C'
        if recent_c <= 3:
            if rng.random() < 0.15:
                return 'C'
            return 'D'
        return 'C'

    # End-game: lock in cooperation unless they have been unreliable.
    if n >= 90:
        if op_d >= 3:
            return 'D'
        return 'C'

    return 'C'
